    /// <summary>Targeted Garden of Sets art; no changes to solo assets, island geometry or navigation.</summary>
    public static partial class ArchiveSetsPolish
    {
        const string Folder=ArchiveTopicSetup.Folder,Prefabs=Folder+"/Art/Prefabs/",Kit=Prefabs+"Archive_T07_Garden_of_Sets.prefab";
        public const string ReadingFontPath=Folder+"/Art/Archive_T7_Reading.asset";
        static Mesh cube,octagon,ring;static TMP_FontAsset font;static Material stone,wood,gold,labels,ink,azure;
        [MenuItem("Tools/Logic Legends/Open Archive/Topics/Polish T7 Garden of Sets")]
        public static string Apply(){
            if(EditorApplication.isPlayingOrWillChangePlaymode||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new InvalidOperationException("Use stopped Play Mode and a saved scene.");SyncSolo();
            var p=GameObject.CreatePrimitive(PrimitiveType.Cube);cube=p.GetComponent<MeshFilter>().sharedMesh;Object.DestroyImmediate(p);octagon=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_BeveledOctagon.asset");ring=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_InlayRing.asset");font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/RulesOfInferenceUI/InferenceBody.asset");stone=Mat("Archive_Topic_Stone");wood=Mat("Archive_Topic_Wood");gold=Mat("Archive_Topic_BrassInlay");labels=Mat("Archive_Topic_WorldLabels");ink=ColorMat("Archive_T7_Ink",new Color(.04f,.16f,.16f),false);azure=ColorMat("Archive_T7_ReviewAzure",new Color(.22f,.8f,.75f),false);
            PrepareReadingFont();
            var aMat=ColorMat("Archive_T7_SetA",new Color(.32f,.65f,.60f),true);var bMat=ColorMat("Archive_T7_SetB",new Color(.57f,.49f,.71f),true);var shared=ColorMat("Archive_T7_Intersection",new Color(.81f,.68f,.38f),true);var uMat=ColorMat("Archive_T7_Universal",new Color(.50f,.59f,.53f),true);
            float theta=Mathf.Acos(2/3.25f);var crescent=new List<Vector2>();Arc(crescent,new Vector2(-2,0),3.25f,theta,2*Mathf.PI-theta,56,true);Arc(crescent,new Vector2(2,0),3.25f,Mathf.PI+theta,Mathf.PI-theta,32,false);Clean(crescent);
            var lens=new List<Vector2>();Arc(lens,new Vector2(-2,0),3.25f,-theta,theta,32,true);Arc(lens,new Vector2(2,0),3.25f,Mathf.PI-theta,Mathf.PI+theta,32,false);Clean(lens);
            var circle=new List<Vector2>();Arc(circle,Vector2.zero,1,0,Mathf.PI*2,64,true);Clean(circle);
            var left=MeshAsset("Archive_T7_Venn_BOnly",crescent);var right=MeshAsset("Archive_T7_Venn_AOnly",crescent.Select(v=>new Vector2(-v.x,v.y)).Reverse().ToList());var overlap=MeshAsset("Archive_T7_Venn_Intersection",lens);var circleAsset=MeshAsset("Archive_T7_Circle",circle);var universal=MeshAsset("Archive_T7_Universal",new List<Vector2>{new Vector2(-5.6f,-4.4f),new Vector2(5.6f,-4.4f),new Vector2(5.6f,4.4f),new Vector2(-5.6f,4.4f)});
            var block=Block();var supply=Supply();var region=RegionLabel();var kit=PrefabUtility.LoadPrefabContents(Kit);
            try{var before=kit.GetComponentsInChildren<Collider>(true).Select(EditorJsonUtility.ToJson).ToArray();foreach(var old in kit.transform.Cast<Transform>().Where(t=>t.name=="T7_Visual_Identity"||t.name=="Set_A_Region"||t.name=="Set_B_Region"||t.name=="Universal_Set_Edge").ToArray())Object.DestroyImmediate(old.gameObject);var root=new GameObject("T7_Visual_Identity").transform;root.SetParent(kit.transform,false);
                var art=kit.GetComponent<ArchiveSetsPresentation>();if(art==null)art=kit.AddComponent<ArchiveSetsPresentation>();art.blockPrefab=block;art.supplyPrefab=supply;art.regionLabelPrefab=region;art.aOnlyMesh=right;art.bOnlyMesh=left;art.intersectionMesh=overlap;art.circleMesh=circleAsset;art.universeMesh=universal;art.ringMesh=ring;art.aMaterial=aMat;art.bMaterial=bMat;art.intersectionMaterial=shared;art.edgeMaterial=gold;art.universeMaterial=uMat;
                art.correctSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Graph/Correct.wav");art.takeSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Assets/Sounds Effects/Small Sound Kit/Magic/Mgc_Ice_Arrow_Cast_01.wav");art.placeSound=art.takeSound;art.incorrectSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Assets/Sounds Effects/Small Sound Kit/Magic/Mgc_Electric_Hit_01.wav");art.sparkMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_RuleCrystal.asset");art.sparkMaterial=Mat("Archive_T1_Sparks");art.progressMarks=new Renderer[5];
                for(int i=0;i<5;i++){float x=(2-i)*.65f;Part(root,"Sets_Progress_Brass_"+i,octagon,gold,new Vector3(x,.07f,6.4f),new Vector3(.48f,.07f,.48f));art.progressMarks[i]=Part(root,"Sets_Progress_Seal_"+i,octagon,azure,new Vector3(x,.11f,6.4f),new Vector3(.33f,.025f,.33f)).GetComponent<Renderer>();}var t=Text(root,"Sets_Entry_Inscription","READ THE SETS   →   MOVE THE ELEMENTS",new Vector3(0,.09f,5.75f),new Vector2(8,.6f),3.2f);t.transform.localRotation=Quaternion.Euler(90,180,0);t.color=new Color(.05f,.28f,.28f);
                art.readingFont=font;
                var st=kit.GetComponent<ArchiveTopicStation>();st.title.text="T7  SETS\nGarden of Sets";st.board.text="GARDEN OF SETS\nTwo questions per challenge.\nRead the Book to begin.";st.GetComponentInChildren<ArchiveAnimatedBook>().bookRig.localScale=Vector3.one*.75f;
                if(!before.SequenceEqual(kit.GetComponentsInChildren<Collider>(true).Select(EditorJsonUtility.ToJson)))throw new InvalidOperationException("T7 collision changed.");PrefabUtility.SaveAsPrefabAsset(kit,Kit);
            }finally{PrefabUtility.UnloadPrefabContents(kit);}return "Saved updated T7 banks, three reusable props and five non-overlapping floor meshes. Solo scene and island retained.";
        }
        static void PrepareReadingFont(){
            font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(ReadingFontPath);
            if(font==null){if(!AssetDatabase.CopyAsset("Assets/RulesOfInferenceUI/InferenceBody.asset",ReadingFontPath))throw new InvalidOperationException("Cannot create T7 reading font.");font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(ReadingFontPath);}
            font.fallbackFontAssetTable=new[]{AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/FINAL_ASSETS/MAPS/REMADE/Induction/Induction Math.asset"),AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/FINAL_ASSETS/MAPS/REMADE/MULTIPLAYER/OPEN_ARCHIVE/Cinematics/VFX/CrimsonBarrier/Fonts/Crimson_NotoSansMath_SDF.asset")}.Concat(font.fallbackFontAssetTable??new List<TMP_FontAsset>()).Where(f=>f!=null&&f!=font).Distinct().ToList();
            EditorUtility.SetDirty(font);AssetDatabase.SaveAssetIfDirty(font);
            var material=Mat("Archive_T7_WorldLabels");if(material==null){material=new Material(labels){name="Archive_T7_WorldLabels"};AssetDatabase.CreateAsset(material,Folder+"/Art/Materials/Archive_T7_WorldLabels.mat");}material.mainTexture=font.atlasTexture;labels=material;EditorUtility.SetDirty(labels);AssetDatabase.SaveAssetIfDirty(labels);
        }
        static GameObject Block(){var root=new GameObject("Archive_T7_NumberBlock");Part(root.transform,"Element_Core",cube,wood,new Vector3(0,.19f,0),Vector3.one*.36f);Part(root.transform,"Review_Rim",octagon,azure,new Vector3(0,.02f,0),new Vector3(.47f,.10f,.47f));Text(root.transform,"Element_Number","99",new Vector3(0,.65f,0),new Vector2(1,.65f),5.0f);return Save(root,"Archive_T7_NumberBlock.prefab");}
        static GameObject Supply(){var root=new GameObject("Archive_T7_ElementSupply");Part(root.transform,"Supply_Stone",octagon,stone,Vector3.zero,new Vector3(.95f,.25f,.95f));Part(root.transform,"Supply_Inlay",ring,gold,new Vector3(0,.12f,0),Vector3.one*.82f);return Save(root,"Archive_T7_ElementSupply.prefab");}
        static GameObject RegionLabel(){var root=new GameObject("Archive_T7_RegionMarker");var t=Text(root.transform,"Region_Name","A ∩ B",new Vector3(0,.045f,1.45f),new Vector2(3.1f,.58f),3.5f);t.transform.localRotation=Quaternion.Euler(90,180,0);t.color=new Color(.025f,.12f,.14f);return Save(root,"Archive_T7_RegionMarker.prefab");}
        static void Arc(List<Vector2> points,Vector2 center,float radius,float from,float to,int segments,bool first){for(int i=first?0:1;i<=segments;i++){float a=Mathf.Lerp(from,to,i/(float)segments);points.Add(center+new Vector2(Mathf.Cos(a),Mathf.Sin(a))*radius);}}
        static void Clean(List<Vector2> p){if(p.Count>1&&(p[p.Count-1]-p[0]).sqrMagnitude<.00001f)p.RemoveAt(p.Count-1);for(int i=p.Count-1;i>0;i--)if((p[i]-p[i-1]).sqrMagnitude<.000001f)p.RemoveAt(i);}
        static float Cross(Vector2 a,Vector2 b)=>a.x*b.y-a.y*b.x;
        static Mesh MeshAsset(string name,List<Vector2> p){var remaining=Enumerable.Range(0,p.Count).ToList();var triangles=new List<int>();int guard=0;while(remaining.Count>3&&guard++<p.Count*p.Count){bool found=false;for(int j=0;j<remaining.Count;j++){int a=remaining[(j+remaining.Count-1)%remaining.Count],b=remaining[j],c=remaining[(j+1)%remaining.Count];if(Cross(p[b]-p[a],p[c]-p[b])<=.0000001f)continue;bool occupied=remaining.Any(i=>i!=a&&i!=b&&i!=c&&Cross(p[b]-p[a],p[i]-p[a])>-.0000001f&&Cross(p[c]-p[b],p[i]-p[b])>-.0000001f&&Cross(p[a]-p[c],p[i]-p[c])>-.0000001f);if(occupied)continue;triangles.AddRange(new[]{a,c,b});remaining.RemoveAt(j);found=true;break;}if(!found)throw new InvalidOperationException("Cannot triangulate Sets region "+name);}if(remaining.Count==3)triangles.AddRange(new[]{remaining[0],remaining[2],remaining[1]});string path=Folder+"/Art/Meshes/"+name+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh{name=name};AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.vertices=p.Select(v=>new Vector3(v.x,0,v.y)).ToArray();mesh.normals=p.Select(_=>Vector3.up).ToArray();mesh.uv=p.Select(v=>new Vector2((v.x+6)/12,(v.y+6)/12)).ToArray();mesh.triangles=triangles.ToArray();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);AssetDatabase.SaveAssetIfDirty(mesh);return mesh;}
        static GameObject Save(GameObject root,string file){var asset=PrefabUtility.SaveAsPrefabAsset(root,Prefabs+file);Object.DestroyImmediate(root);return asset;}
        static Material Mat(string n)=>AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Art/Materials/"+n+".mat");
        static Material ColorMat(string name,Color color,bool textured){var m=Mat(name);if(m==null){m=textured?new Material(stone):new Material(Shader.Find("Universal Render Pipeline/Unlit"));m.name=name;m.enableInstancing=true;AssetDatabase.CreateAsset(m,Folder+"/Art/Materials/"+name+".mat");}m.SetColor("_BaseColor",color);EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);return m;}
        static TMP_Text Text(Transform parent,string name,string value,Vector3 position,Vector2 size,float fontSize){var t=new GameObject(name).AddComponent<TextMeshPro>();t.transform.SetParent(parent,false);t.transform.localPosition=position;t.rectTransform.sizeDelta=size;t.font=font;t.fontSharedMaterial=labels;t.text=value;t.fontSize=fontSize;t.enableAutoSizing=true;t.fontSizeMax=fontSize;t.fontSizeMin=2;t.textWrappingMode=TextWrappingModes.NoWrap;t.richText=false;t.alignment=TextAlignmentOptions.Center;t.color=new Color(1,.94f,.79f);t.raycastTarget=false;return t;}
        static Transform Part(Transform parent,string name,Mesh mesh,Material mat,Vector3 pos,Vector3 scale){var t=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer)).transform;t.SetParent(parent,false);t.localPosition=pos;t.localScale=scale;t.GetComponent<MeshFilter>().sharedMesh=mesh;var r=t.GetComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;return t;}
    }
